window.WORD_AI_EXAMPLE_CHUNK = {"entries":{"magnetic":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"有磁性的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"有吸引力的"}],"examples":[{"sentence":"Iron filings gather along the magnetic field lines around a bar magnet.","translation":"铁屑沿条形磁铁周围的磁场线聚集。","targetForm":"magnetic","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The speaker had a magnetic confidence that held the audience's attention throughout the lecture.","translation":"演讲者有一种吸引人的自信，在整场讲座中都抓住了听众注意力。","targetForm":"magnetic","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Magnetic resonance imaging can reveal details that ordinary X-rays cannot show.","translation":"磁共振成像能显示普通X光无法呈现的细节。","targetForm":"Magnetic","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The researcher measured how magnetic materials respond when the temperature changes.","translation":"研究人员测量了磁性材料在温度变化时如何响应。","targetForm":"magnetic","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Her magnetic personality made new volunteers feel welcome from the first meeting.","translation":"她富有吸引力的个性让新志愿者从第一次见面起就感到受欢迎。","targetForm":"magnetic","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"marriage":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"结婚"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"婚姻"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"合并"}],"examples":[{"sentence":"The couple discussed their expectations openly before deciding to enter into marriage.","translation":"这对情侣在决定结婚前坦诚讨论了彼此的期待。","targetForm":"marriage","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Their marriage became stronger when they learned to resolve disagreements without blame.","translation":"当他们学会不互相指责地解决分歧时，婚姻变得更稳固。","targetForm":"marriage","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The legal changes gave equal protection to every marriage recognised by the state.","translation":"法律变更为国家承认的每段婚姻提供平等保护。","targetForm":"marriage","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The exhibition explores the marriage of traditional crafts with modern industrial design.","translation":"展览探讨传统工艺与现代工业设计的结合。","targetForm":"marriage","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The wedding guests celebrated the marriage with music, food, and speeches.","translation":"婚礼宾客用音乐、食物和致辞庆祝这段婚姻。","targetForm":"marriage","senseId":"source-n-1","sourceSenseId":"n-1"}]},"mature":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"成熟的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"到期的"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"成熟"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"到期"}],"examples":[{"sentence":"Her mature handling of the crisis, which involved careful deliberation and empathy, earned her the respect of her peers.","translation":"她对危机的成熟处理，包括深思熟虑和同理心，赢得了同事们的尊重。","targetForm":"mature","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The mature oak tree, which had stood for centuries, provided a habitat for countless species of birds and insects.","translation":"这棵成熟的橡树已经矗立了几个世纪，为无数鸟类和昆虫提供了栖息地。","targetForm":"mature","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The certificate of deposit will mature next month, at which point we can reinvest the funds at a higher rate.","translation":"这张存单下个月到期，届时我们可以将资金以更高的利率再投资。","targetForm":"mature","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The wine is aged in oak barrels to mature, a process that enhances its complexity and smoothness.","translation":"葡萄酒在橡木桶中陈酿以使其成熟，这一过程增强了其复杂性和顺滑度。","targetForm":"mature","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"When the insurance policy matured, she received a substantial payout that allowed her to retire comfortably.","translation":"当保险单到期时，她获得了一笔可观的赔付，使她能够舒适地退休。","targetForm":"matured","senseId":"source-v-3","sourceSenseId":"v-3"}]},"machine":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"机器"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"自动售货机"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"机构"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"以机器制造"},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"机械般工作的人"}],"examples":[{"sentence":"The machine stopped automatically when a sensor detected that the guard had been opened.","translation":"传感器检测到防护罩被打开时，机器自动停止。","targetForm":"machine","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A vending machine near the station sells drinks and simple snacks late at night.","translation":"车站附近的一台自动售货机深夜仍出售饮料和简餐。","targetForm":"machine","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The organisation had become a political machine that rewarded loyalty more than ability.","translation":"该组织已变成一个重忠诚胜过重能力的政治机构。","targetForm":"machine","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The factory machines metal parts to precise measurements for medical equipment.","translation":"工厂按精确尺寸机械加工医疗设备的金属部件。","targetForm":"machines","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although he worked tirelessly, his colleagues knew he was not a machine and needed rest.","translation":"尽管他不知疲倦地工作，同事们知道他不是机器，也需要休息。","targetForm":"machine","senseId":"source-n-5","sourceSenseId":"n-5"}]},"maths":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"数学"}],"examples":[{"sentence":"Her proficiency in maths enabled her to solve complex problems that baffled many of her peers.","translation":"她在数学方面的熟练使她能够解决许多同龄人无法理解的复杂问题。","targetForm":"maths","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The professor emphasized that a solid foundation in maths is essential for advanced studies in physics.","translation":"教授强调，扎实的数学基础对于物理学的高级研究至关重要。","targetForm":"maths","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Despite his initial struggles, he developed a genuine passion for maths after attending an inspiring lecture.","translation":"尽管最初困难重重，但在参加了一场鼓舞人心的讲座后，他对数学产生了真正的热情。","targetForm":"maths","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The curriculum was redesigned to integrate maths with real-world applications, making the subject more engaging for students.","translation":"课程经过重新设计，将数学与现实应用相结合，使这门学科对学生更具吸引力。","targetForm":"maths","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Many economists rely on advanced maths to model market behaviors and predict future trends.","translation":"许多经济学家依赖高等数学来模拟市场行为并预测未来趋势。","targetForm":"maths","senseId":"source-n-1","sourceSenseId":"n-1"}]},"mask":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"面具"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"假面具"}],"examples":[{"sentence":"Because the mask filters harmful particles, it is essential for workers in dusty industrial settings.","translation":"由于口罩能过滤有害颗粒，它对在多尘工业环境工作的人员至关重要。","targetForm":"mask","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The artist created a mask that combined traditional motifs with modern materials to represent cultural exchange.","translation":"艺术家创作了一张结合传统图案与现代材料的面具，以表现文化交流。","targetForm":"mask","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although a mask can provide anonymity, it may also encourage conduct that people would avoid face to face.","translation":"尽管面具可以提供匿名性，它也可能鼓励人们做出面对面时会避免的行为。","targetForm":"mask","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"To fit properly, the mask must seal around the nose and mouth without causing discomfort.","translation":"为确保贴合，口罩必须紧贴鼻子和嘴周围而不造成不适。","targetForm":"mask","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"During the pandemic, masks served as barriers against infection and symbols of collective responsibility.","translation":"疫情期间，口罩既是防感染的屏障，也是集体责任的象征。","targetForm":"masks","senseId":"source-n-1","sourceSenseId":"n-1"}]},"map":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"地图"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"天体图"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"绘制...地图"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"映射"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"映像"}],"examples":[{"sentence":"The map showed a safer route that avoided the road damaged by the storm.","translation":"地图显示了一条避开暴风雨损坏道路的更安全路线。","targetForm":"map","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Astronomers used a detailed map of the sky to identify the newly observed object.","translation":"天文学家用一张详细天体图识别新观测到的物体。","targetForm":"map","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The team mapped the flood-prone areas before recommending where new homes could be built.","translation":"团队在建议新住房选址前绘制了易受洪水影响区域的地图。","targetForm":"mapped","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Researchers mapped how information travelled through the community after the emergency announcement.","translation":"研究人员绘制了紧急公告后信息如何在社区传播的图谱。","targetForm":"mapped","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"A clear map of responsibilities can prevent small tasks from being forgotten.","translation":"清晰的职责图可以防止小任务被遗忘。","targetForm":"map","senseId":"source-n-3","sourceSenseId":"n-3"}]},"magnet":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"磁铁"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"有吸引力之物"}],"examples":[{"sentence":"Because a magnet attracts iron, engineers use it in devices that separate metal from mixed materials.","translation":"由于磁铁吸引铁，工程师把它用于从混合材料中分离金属的设备。","targetForm":"magnet","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The students tested how the magnet's strength changed when different materials were placed nearby.","translation":"学生们测试了不同材料放在附近时磁铁强度如何变化。","targetForm":"magnet","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the city is small, its arts scene is a magnet for creative professionals.","translation":"尽管这座城市不大，它的艺术氛围仍是吸引创意专业人士的磁石。","targetForm":"magnet","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The research institute acts as a magnet for scientists who need advanced facilities.","translation":"这家研究所像磁石一样吸引需要先进设施的科学家。","targetForm":"magnet","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Low tax rates can become a magnet for businesses, thereby accelerating regional economic growth.","translation":"较低税率能成为吸引企业的磁石，从而加快地区经济增长。","targetForm":"magnet","senseId":"source-n-3","sourceSenseId":"n-3"}]},"man":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"男人"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"为...配备人手"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"操纵"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"人"}],"examples":[{"sentence":"The man at the information desk explained where visitors should leave their bags.","translation":"咨询台的那位男士说明了访客应在哪里寄存包。","targetForm":"man","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Every man and woman on the team received the same safety training before departure.","translation":"团队中的每位男性和女性在出发前都接受了同样的安全培训。","targetForm":"man","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Volunteers manned the help desk throughout the festival and answered practical questions.","translation":"志愿者在整个节日期间值守服务台并回答实际问题。","targetForm":"manned","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The small crew manned the research vessel during the overnight survey.","translation":"小型船员团队在夜间调查期间操作研究船。","targetForm":"manned","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The interview shows how one man can influence a community through patient, consistent work.","translation":"这篇访谈展示一个人如何通过耐心而持续的工作影响社区。","targetForm":"man","senseId":"source-n-3","sourceSenseId":"n-3"}]},"matter":{"senseGroups":[{"id":"source-n-6","partOfSpeech":"n.","sourceSenseIds":["n-6"],"sense":"重要"}],"examples":[{"sentence":"Oil production does not matter; exports do, which means that announcements of increases in oil output are irrelevant for prices.","translation":"这表明OPEC成员国国和石油进口国的政策制定者们都不应该忘记：应对高油价的唯一方法就是维持高油价。","targetForm":"matter","senseId":"source-n-6","sourceSenseId":"n-6"}]},"mammal":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"哺乳动物"}],"examples":[{"sentence":"The blue whale is the largest mammal ever known to have existed on Earth.","translation":"蓝鲸是地球上已知存在过的最大的哺乳动物。","targetForm":"mammal","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Marine mammals such as dolphins and seals have adapted remarkably well to life in the ocean.","translation":"海豚和海豹等海洋哺乳动物已经非常出色地适应了海洋生活。","targetForm":"mammals","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The fossil record indicates that early mammals appeared during the Mesozoic era.","translation":"化石记录表明，早期哺乳动物出现在中生代。","targetForm":"mammals","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A distinguishing feature of every mammal is the presence of mammary glands for feeding their young.","translation":"每种哺乳动物的一个显著特征是存在用于喂养幼崽的乳腺。","targetForm":"mammal","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The conservation program aims to protect endangered mammals from habitat loss and poaching.","translation":"该保护计划旨在保护濒危哺乳动物免受栖息地丧失和偷猎的威胁。","targetForm":"mammals","senseId":"source-n-1","sourceSenseId":"n-1"}]},"mat":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"垫"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"丛"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"衬边"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"粗糙的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"无光泽的"}],"examples":[{"sentence":"The yoga instructor placed a thick mat on the floor before beginning the session.","translation":"瑜伽教练在开始课程前在地板上放了一块厚垫子。","targetForm":"mat","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A dense mat of ivy covered the old garden wall, providing a habitat for small birds.","translation":"浓密的一丛常春藤覆盖了古老的花园墙壁，为小鸟提供了栖息地。","targetForm":"mat","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The framer carefully selected a cream-colored mat to complement the watercolor painting.","translation":"装裱师精心挑选了一张奶油色的衬边来搭配那幅水彩画。","targetForm":"mat","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The old photograph had a mat surface that softened the details of the portrait.","translation":"那张旧照片的表面粗糙，柔化了肖像的细节。","targetForm":"mat","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The painter applied a mat varnish to eliminate unwanted reflections on the canvas.","translation":"画家涂了一层无光泽的清漆，以消除画布上不必要的反光。","targetForm":"mat","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"manufacture":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"制造"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"制造"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"假造"}],"examples":[{"sentence":"The manufacture of medical equipment requires careful control of materials and testing.","translation":"医疗设备制造需要对材料和测试进行严格控制。","targetForm":"manufacture","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Local manufacture creates jobs and can reduce the cost of transporting essential goods.","translation":"本地制造创造就业，也能降低运输必需品的成本。","targetForm":"manufacture","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The company manufactures low-cost filters that make unsafe water suitable for basic household use.","translation":"该公司制造低成本滤水器，使不安全的水可供家庭基本使用。","targetForm":"manufactures","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The investigation found that several documents had been manufactured to support a false claim.","translation":"调查发现数份文件被伪造以支持虚假主张。","targetForm":"manufactured","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The region is known for the manufacture of high-quality textiles from locally grown fibres.","translation":"该地区以用本地种植纤维制造优质纺织品而闻名。","targetForm":"manufacture","senseId":"source-n-2","sourceSenseId":"n-2"}]},"maneuver":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"策略"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"调遣"}],"examples":[{"sentence":"When negotiating a contract, a skilled lawyer can maneuver through legal loopholes to protect their client's interests.","translation":"在谈判合同时，一位熟练的律师能巧妙地利用法律漏洞来保护客户的利益。","targetForm":"maneuver","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The spacecraft performed a complex maneuver to enter the planet's orbit, which allowed scientists to study its atmosphere.","translation":"航天器执行了一次复杂的机动以进入行星轨道，这使得科学家能够研究其大气层。","targetForm":"maneuver","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although the driver attempted a risky maneuver to overtake the truck, he lost control and caused a serious accident.","translation":"尽管司机试图进行一次危险的机动以超越卡车，但他失去了控制并造成了严重事故。","targetForm":"maneuver","senseId":"source-n-2","sourceSenseId":"n-2"}]},"maid":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"女仆"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"少女"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"未婚女子"}],"examples":[{"sentence":"The historical record describes a maid who worked in the household for more than twenty years.","translation":"历史记录描述了一名在该家庭服务二十多年的女仆。","targetForm":"maid","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"In the old ballad, the maid waits by the window for news from her family.","translation":"在这首古老民谣中，少女在窗边等待家人的消息。","targetForm":"maid","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The hotel hired an additional room maid during the busy holiday season.","translation":"酒店在繁忙假期额外雇用了一名客房女服务员。","targetForm":"maid","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The novel uses the word maid to reflect the social language of its historical setting.","translation":"小说使用maid一词，以体现其历史背景中的社会语言。","targetForm":"maid","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The young maid in the portrait is shown holding a basket of flowers.","translation":"肖像中的年轻少女手持一篮鲜花。","targetForm":"maid","senseId":"source-n-1","sourceSenseId":"n-1"}]},"madame":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"夫人"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"女士"},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"主妇"},{"id":"source-n-6","partOfSpeech":"n.","sourceSenseIds":["n-6"],"sense":"(非正式)喜欢差使/指使别人的女子"},{"id":"source-n-7","partOfSpeech":"n.","sourceSenseIds":["n-7"],"sense":"鸨母"}],"examples":[{"sentence":"Madame Dupont, the director of the institute, delivered an inspiring speech at the conference.","translation":"研究所所长杜邦夫人在会议上发表了鼓舞人心的演讲。","targetForm":"Madame","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The boutique owner, a charming madame with impeccable taste, helped me select the perfect gown.","translation":"精品店店主是一位品味无可挑剔的迷人女士，她帮我挑选了完美的礼服。","targetForm":"madame","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"As the madame of the household, she oversaw all domestic affairs with quiet authority.","translation":"作为家庭主妇，她以沉静的权威管理着所有家务。","targetForm":"madame","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"The new manager was a madame who constantly ordered her subordinates around without consideration.","translation":"新经理是个喜欢差使别人的女子，总是不顾他人地指使下属。","targetForm":"madame","senseId":"source-n-6","sourceSenseId":"n-6"},{"sentence":"In the novel, the madame of the establishment was portrayed as a shrewd but compassionate figure.","translation":"在小说中，那家妓院的鸨母被描绘成一个精明但富有同情心的人物。","targetForm":"madame","senseId":"source-n-7","sourceSenseId":"n-7"}]},"maiden":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"少女"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"初次的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"未婚的"}],"examples":[{"sentence":"The young maiden walked gracefully through the garden, her thoughts drifting to distant lands.","translation":"那位年轻少女优雅地走过花园，思绪飘向远方。","targetForm":"maiden","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"In many traditional tales, a brave knight rescues a fair maiden from a fearsome dragon.","translation":"在许多传统故事中，勇敢的骑士从可怕的恶龙手中救出美丽的少女。","targetForm":"maiden","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The researcher published her maiden paper on quantum computing, which garnered immediate attention from the scientific community.","translation":"这位研究员发表了她的第一篇关于量子计算的论文，立即引起了科学界的关注。","targetForm":"maiden","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The ship embarked on its maiden voyage across the Atlantic, carrying hopes of a new era in maritime travel.","translation":"这艘船开始了横跨大西洋的处女航，承载着航海旅行新时代的希望。","targetForm":"maiden","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"She retained her maiden name after marriage, a decision that reflected her professional identity and personal principles.","translation":"她婚后保留了娘家姓，这一决定反映了她的职业身份和个人原则。","targetForm":"maiden","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"manuscript":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"原稿"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"手稿"}],"examples":[{"sentence":"The author donated the original manuscript to the library, thereby ensuring its preservation for future generations.","translation":"作者将原始手稿捐赠给图书馆，从而确保其为后代保存。","targetForm":"manuscript","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"When the manuscript was finally published, it received critical acclaim for its innovative narrative structure.","translation":"当手稿最终出版时，因其创新的叙事结构而获得评论界的好评。","targetForm":"manuscript","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the manuscript was incomplete, the editor recognized its potential and offered a contract.","translation":"尽管手稿尚未完成，编辑还是看出了它的潜力并提供了合同。","targetForm":"manuscript","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the manuscript was handwritten, the publisher required a digital version before typesetting.","translation":"由于手稿是手写的，出版社在排版前要求提供电子版。","targetForm":"manuscript","senseId":"source-n-1","sourceSenseId":"n-1"}]},"marginal":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"最低限度的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"边缘的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"有旁注的"},{"id":"source-adj-4","partOfSpeech":"adj.","sourceSenseIds":["adj-4"],"sense":"缘的","contextReviewed":true}],"examples":[{"sentence":"Although the new system produced a marginal improvement, the team continued to test other approaches.","translation":"尽管新系统只带来了微小改善，团队仍继续测试其他方法。","targetForm":"marginal","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The school offered support to marginal communities that had limited access to public transport.","translation":"学校向获得公共交通机会有限的边缘社区提供支持。","targetForm":"marginal","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"When historians read the marginal notes, they discovered how earlier readers responded to the text.","translation":"当历史学家阅读旁注时，他们发现了早期读者如何回应这篇文本。","targetForm":"marginal","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"Because the treatment affected only a marginal area, the doctor monitored the response closely.","translation":"由于治疗只影响边缘区域，医生密切监测了反应。","targetForm":"marginal","senseId":"source-adj-4","sourceSenseId":"adj-4"},{"sentence":"The policy made a marginal difference to overall costs, although it helped a few small firms.","translation":"这项政策对总体成本影响很小，尽管它帮助了几家小企业。","targetForm":"marginal","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"many":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"许多的"},{"id":"source-pron-1","partOfSpeech":"pron.","sourceSenseIds":["pron-1"],"sense":"许多"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"多数人"}],"examples":[{"sentence":"Many students benefit from setting small weekly goals instead of relying on last-minute effort.","translation":"许多学生通过设定每周小目标受益，而非依赖临时突击。","targetForm":"Many","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Many were surprised that the simple change reduced energy use so quickly.","translation":"许多人惊讶于这个简单改变如此迅速地降低了能耗。","targetForm":"Many","senseId":"source-pron-1","sourceSenseId":"pron-1"},{"sentence":"The many should not be ignored simply because a decision is easier for a powerful few.","translation":"不能仅因决定更有利于强势少数，就忽视多数人的利益。","targetForm":"many","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"There are many reasons to verify a source before using it in an academic essay.","translation":"在学术论文中使用资料前核实来源有许多理由。","targetForm":"many","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Among the many who applied, only a small group had experience with field research.","translation":"在众多申请者中，只有一小部分有田野研究经验。","targetForm":"many","senseId":"source-n-2","sourceSenseId":"n-2"}]},"magic":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"魔术"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"魔法"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"魔术的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"有魔力的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"不可思议的"}],"examples":[{"sentence":"The magician explained that the apparent magic depended on careful timing and hidden preparation.","translation":"魔术师解释说，表面上的魔术依靠精确时机和隐藏准备。","targetForm":"magic","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"For many children, reading can feel like magic because it opens unfamiliar worlds.","translation":"对许多孩子而言，阅读仿佛魔法，因为它打开陌生的世界。","targetForm":"magic","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The theatre used a magic lantern to create moving images on a large screen.","translation":"剧院用幻灯设备在大屏幕上制造移动影像。","targetForm":"magic","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"There is no magic solution to poverty, but sustained investment can improve opportunity.","translation":"贫困没有神奇解方，但持续投资能改善机会。","targetForm":"magic","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The chemistry demonstration seemed magic until the teacher explained the reaction clearly.","translation":"化学演示看似不可思议，直到老师清楚解释反应原理。","targetForm":"magic","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"marital":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"婚姻的"}],"examples":[{"sentence":"Because marital property laws vary significantly across jurisdictions, international couples should seek legal advice to protect their assets.","translation":"由于婚姻财产法在不同司法管辖区差异很大，跨国夫妻应寻求法律建议以保护其资产。","targetForm":"marital","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Although societal attitudes toward marital roles have evolved, traditional expectations still influence the division of household labor in many families.","translation":"尽管社会对婚姻角色的态度已经演变，但传统期望仍然影响着许多家庭的家务分工。","targetForm":"marital","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Through marital counseling, many couples learn to communicate more effectively, which in turn strengthens their emotional bond and mutual respect.","translation":"通过婚姻咨询，许多夫妻学会了更有效地沟通，这反过来又加强了他们的情感纽带和相互尊重。","targetForm":"marital","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"While financial disagreements are a common source of marital conflict, couples who establish transparent budgeting practices often experience greater harmony.","translation":"尽管财务分歧是婚姻冲突的常见根源，但建立透明预算做法的夫妻往往能体验到更大的和谐。","targetForm":"marital","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The study found that marital satisfaction tends to decline after the birth of the first child, unless both partners actively share caregiving responsibilities.","translation":"研究发现，第一个孩子出生后婚姻满意度往往会下降，除非双方积极分担育儿责任。","targetForm":"marital","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"may":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"五月"},{"id":"source-aux-2","partOfSpeech":"aux.","sourceSenseIds":["aux-2"],"sense":"可以"},{"id":"source-aux-1","partOfSpeech":"aux.","sourceSenseIds":["aux-1"],"sense":"愿能"}],"examples":[{"sentence":"In May, the university opens its gardens to the public before the summer research programme begins.","translation":"五月，大学会在暑期研究项目开始前向公众开放花园。","targetForm":"May","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The results may change when the sample is expanded, so the researchers described their conclusion as provisional.","translation":"样本扩大后结果可能会变化，因此研究人员把结论描述为暂时的。","targetForm":"may","senseId":"source-aux-2","sourceSenseId":"aux-2"},{"sentence":"Applicants may submit a digital portfolio provided that every image is clearly labelled and properly credited.","translation":"申请者可以提交电子作品集，前提是每张图片都有清晰标注并正确署名。","targetForm":"may","senseId":"source-aux-2","sourceSenseId":"aux-2"},{"sentence":"May the new library become a place where curiosity is valued as highly as achievement.","translation":"愿这座新图书馆成为一个重视好奇心如同重视成就的地方。","targetForm":"May","senseId":"source-aux-1","sourceSenseId":"aux-1"},{"sentence":"Although the route appears direct, heavy rain may delay the delivery until the following morning.","translation":"尽管路线看似直接，大雨仍可能使配送延迟到第二天上午。","targetForm":"may","senseId":"source-aux-2","sourceSenseId":"aux-2"}]},"magazine":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"杂志"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"仓库"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"胶卷盒"}],"examples":[{"sentence":"The magazine published a balanced article on how cities can reduce traffic pollution.","translation":"这本杂志发表了一篇平衡讨论城市如何减少交通污染的文章。","targetForm":"magazine","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The port authority built a secure magazine for storing materials that require careful handling.","translation":"港务局建造了一个安全仓库，用于存放需要谨慎处理的材料。","targetForm":"magazine","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The photographer checked that the film magazine was correctly attached before taking the picture.","translation":"摄影师拍照前检查胶卷盒是否正确安装。","targetForm":"magazine","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The editor asked readers to respond to the magazine's investigation with evidence rather than rumours.","translation":"编辑请读者以证据而非传言回应杂志的调查报道。","targetForm":"magazine","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The museum displayed an empty magazine to explain how older cameras stored film.","translation":"博物馆展示了一个空胶卷盒，以说明旧相机如何储存胶卷。","targetForm":"magazine","senseId":"source-n-4","sourceSenseId":"n-4"}]},"marine":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"舰队"}],"examples":[{"sentence":"Because marine transportation is vital for global trade, ports must operate efficiently around the clock.","translation":"因为海运对全球贸易至关重要，港口必须全天候高效运作。","targetForm":"marine","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"To ensure sustainable fisheries, policymakers must consider the complex dynamics of marine food webs.","translation":"为了确保渔业的可持续性，政策制定者必须考虑海洋食物网的复杂动态。","targetForm":"marine","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"While marine biologists study deep-sea organisms, they often discover species that defy conventional classification.","translation":"当海洋生物学家研究深海生物时，他们经常发现挑战传统分类的物种。","targetForm":"marine","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although marine ecosystems are resilient, they are increasingly threatened by pollution and overfishing.","translation":"尽管海洋生态系统具有恢复力，但它们正日益受到污染和过度捕捞的威胁。","targetForm":"marine","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The government established a marine sanctuary, which protects endangered species from human interference.","translation":"政府建立了一个海洋保护区，这保护了濒危物种免受人类干扰。","targetForm":"marine","senseId":"source-n-1","sourceSenseId":"n-1"}]},"maximum":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"最大量"}],"examples":[{"sentence":"Please consider that the maximum doesn't exist in some circumstances.","translation":"请考虑一下，最大值在有些情况下是不存在的。","targetForm":"maximum","senseId":"source-n-2","sourceSenseId":"n-2"}]},"masculine":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"男性"}],"examples":[{"sentence":"Confidence and courage are not exclusively masculine traits—they are values that everyone can aspire to.","translation":"自信与勇气不仅是男性特质，也可以是所有人都能追求的价值。","targetForm":"masculine","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Confidence and courage are not just masculine traits; they are values anyone can strive for.","translation":"自信与勇气不仅是男性特质，也可以是所有人都能追求的价值。","targetForm":"masculine","senseId":"source-n-2","sourceSenseId":"n-2"}]},"malignant":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"有恶意的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"恶性的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"有害的"}],"examples":[{"sentence":"Because malignant rumors can irreparably damage a person's reputation, journalists must verify facts before publishing sensitive stories.","translation":"由于恶意谣言可能对个人声誉造成不可挽回的损害，记者在发表敏感报道前必须核实事实。","targetForm":"malignant","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the initial biopsy suggested a benign growth, subsequent imaging revealed a malignant tumor that required immediate surgical intervention.","translation":"尽管最初的活检提示为良性增生，但随后的影像学检查显示为恶性肿瘤，需要立即进行手术干预。","targetForm":"malignant","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Despite advances in targeted therapy, treating malignant melanoma remains challenging because the cancer can develop resistance to drugs over time.","translation":"尽管靶向治疗取得了进展，但治疗恶性黑色素瘤仍然具有挑战性，因为癌症会随时间对药物产生耐药性。","targetForm":"malignant","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The oncologist explained that malignant cells often metastasize through the lymphatic system, which makes early detection crucial for effective treatment.","translation":"肿瘤科医生解释说，恶性细胞常通过淋巴系统转移，这使得早期发现对有效治疗至关重要。","targetForm":"malignant","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"When a malignant ideology takes root in a community, it can erode social trust and lead to widespread discrimination, thereby undermining public harmony.","translation":"当一种有害的意识形态在社区中扎根时，它会侵蚀社会信任并导致广泛的歧视，从而破坏公共和谐。","targetForm":"malignant","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"material":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"材料"}],"examples":[{"sentence":"New Zealand students have developed sustainable materials made from cabbage tree leaves and flax that could soon be used to make high-performance skis, kayaks and skateboards.","translation":"纽西兰学生开发出由高丽菜树叶和亚麻制成的永续材料，很快就能用于制造高性能滑雪板、皮划艇和滑板。","targetForm":"materials","senseId":"source-n-1","sourceSenseId":"n-1"}]},"marvelous":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"了不起的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"令人惊异的"}],"examples":[{"sentence":"The restoration team did a marvelous job, revealing colours that had been hidden beneath dust for generations.","translation":"修复团队完成了一项了不起的工作，揭示了尘土下隐藏数代的颜色。","targetForm":"marvelous","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Although the weather was difficult, the expedition produced marvelous photographs that helped researchers identify the rare species.","translation":"尽管天气恶劣，考察队仍拍摄了精彩照片，帮助研究人员识别这种罕见物种。","targetForm":"marvelous","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The lecturer gave a marvelous explanation of the theory, using an everyday example that made the abstract idea clear.","translation":"讲师对该理论作了极好的解释，用一个日常例子使抽象概念变得清楚。","targetForm":"marvelous","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Because the volunteers worked across several languages, the community project achieved a marvelous level of cooperation.","translation":"由于志愿者跨越多种语言协作，这个社区项目达到了非凡的合作水平。","targetForm":"marvelous","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The museum's new lighting created a marvelous effect by making small details visible without harming the paintings.","translation":"博物馆的新照明营造了奇妙效果，让细小细节可见而不损害画作。","targetForm":"marvelous","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"manual":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"手册"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"手动的"},{"id":"source-adj-4","partOfSpeech":"adj.","sourceSenseIds":["adj-4"],"sense":"体力的"},{"id":"source-other-1","partOfSpeech":"计算机","sourceSenseIds":["other-1"],"sense":"人工的","contextReviewed":true}],"examples":[{"sentence":"The safety manual explains what staff should do if the alarm sounds during the experiment.","translation":"安全手册说明实验期间警报响起时员工应如何处理。","targetForm":"manual","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Please consult the manual before changing any of the settings on the machine.","translation":"更改机器任何设置前，请查阅手册。","targetForm":"manual","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The device can operate in manual mode when the automatic system is being repaired.","translation":"自动系统维修时，该设备可在手动模式下运行。","targetForm":"manual","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Many rural families still rely on manual labour during the harvest season.","translation":"许多农村家庭在收获季节仍依赖体力劳动。","targetForm":"manual","senseId":"source-adj-4","sourceSenseId":"adj-4"},{"sentence":"The database requires manual review when an uploaded form contains incomplete information.","translation":"上传表格包含不完整信息时，数据库需要人工审核。","targetForm":"manual","senseId":"source-other-1","sourceSenseId":"other-1"}]},"massacre":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"大屠杀"}],"examples":[{"sentence":"The Chinese government controlled the internet to prevent the people from knowing the truth of the Tiananmen Square Massacre.","translation":"中国政府控制了网络，以免让人民知道六四事件的真相。","targetForm":"massacre","senseId":"source-n-1","sourceSenseId":"n-1"}]},"massive":{"senseGroups":[{"id":"source-adj-6","partOfSpeech":"adj.","sourceSenseIds":["adj-6"],"sense":"大量的","contextReviewed":true}],"examples":[{"sentence":"Eighth, some emerging-market economies with weaker economic fundamentals may not be able to avoid a severe financial crisis, despite massive IMF support.","translation":"第八，有些经济基本面薄弱的新兴经济体，尽管有国际货币基金组织的大力支持，可能仍然无法避免一场严重的金融危机。","targetForm":"massive","senseId":"source-adj-6","sourceSenseId":"adj-6"},{"sentence":"It is likely that Pachauri is right and Gore is wrong: neither China nor India will commit to significant cuts without a massive payoff.","translation":"很可能帕乔里对了而戈尔错了：在没有巨大收益的情况下，中国和印度都不会承诺进行重大的减排。","targetForm":"massive","senseId":"source-adj-6","sourceSenseId":"adj-6"}]},"marry":{"senseGroups":[{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"结婚"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"嫁"}],"examples":[{"sentence":"Because of the change in Canadian marriage laws, many American homosexuals came to Canada to get married.","translation":"由于加拿大婚姻法的改变，所以很多美国同性恋者去了加拿大结婚。","targetForm":"married","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"When they heard that their teacher was going to get married, everyone wanted to attend her wedding.","translation":"听说老师要结婚，大家都想参加她的婚礼。","targetForm":"married","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"If you marry a chicken, follow the chicken; if you marry a dog, follow the dog.","translation":"嫁鸡随鸡嫁狗随狗。","targetForm":"marry","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"A person is a bachelor if and only if that person is a marriageable man who has never married.","translation":"当且仅当一个人是个没有结婚并可以结婚的男人，那个人是个未娶。","targetForm":"married","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"She married John, not because she loved him, but because he was a rich man.","translation":"她嫁了 John，不是因为爱他，而是因为 John 是个有钱人。","targetForm":"married","senseId":"source-v-3","sourceSenseId":"v-3"}]},"marble":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"大理石"}],"examples":[{"sentence":"Thousands of laborers and craftsmen toiled for 22 years to craft the stunning white marble edifice.","translation":"数千名工人和工匠辛勤工作了 22 年，才打造出这座令人惊叹的白色大理石建筑。","targetForm":"marble","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Thousands of workers and artisans toiled for 22 years to create this breathtaking white marble structure.","translation":"数千名工人和工匠辛勤工作了 22 年，才打造出这座令人惊叹的白色大理石建筑。","targetForm":"marble","senseId":"source-n-1","sourceSenseId":"n-1"}]},"mankind":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"人类"}],"examples":[{"sentence":"Climate change is a challenge for mankind because its effects cross national borders.","translation":"气候变化是人类面临的挑战，因为其影响跨越国界。","targetForm":"mankind","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The invention transformed mankind's ability to share information across long distances.","translation":"这项发明改变了人类跨越长距离分享信息的能力。","targetForm":"mankind","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The historian used mankind in its older sense and explained why inclusive language is now preferred.","translation":"这位历史学家以其旧义使用mankind，并解释了为何如今更倡导包容性语言。","targetForm":"mankind","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The story asks whether mankind can use technology wisely without damaging the natural world.","translation":"这个故事提出疑问：人类能否明智使用技术而不破坏自然世界。","targetForm":"mankind","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"For all mankind's achievements, many communities still lack access to basic healthcare.","translation":"尽管人类成就众多，许多社区仍无法获得基本医疗服务。","targetForm":"mankind","senseId":"source-n-1","sourceSenseId":"n-1"}]},"march":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"三月"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"进行"},{"id":"source-n-6","partOfSpeech":"n.","sourceSenseIds":["n-6"],"sense":"进行曲"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"进军"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"前进"}],"examples":[{"sentence":"The new policy will take effect in March, after schools have received the revised guidance.","translation":"学校收到修订指南后，新政策将于三月生效。","targetForm":"March","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The workers joined a peaceful march to call for safer conditions in the factory.","translation":"工人参加和平游行，呼吁工厂提供更安全的条件。","targetForm":"march","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The band played a slow march as the ceremony began in the town square.","translation":"仪式在城镇广场开始时，乐队演奏了一首缓慢的进行曲。","targetForm":"march","senseId":"source-n-6","sourceSenseId":"n-6"},{"sentence":"The students marched across campus to deliver their petition to the university office.","translation":"学生们穿过校园行进，将请愿书递交给大学办公室。","targetForm":"marched","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Scientific progress marches forward when researchers share methods as well as results.","translation":"当研究人员分享方法和结果时，科学进步便不断向前。","targetForm":"marches","senseId":"source-v-2","sourceSenseId":"v-2"}]},"mail":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"邮件"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"邮政"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"邮寄"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"盔甲"},{"id":"source-other-1","partOfSpeech":"计算机","sourceSenseIds":["other-1"],"sense":"电子邮件","contextReviewed":true}],"examples":[{"sentence":"The report arrived in the morning mail, together with a letter requesting further information.","translation":"报告随同一封要求补充信息的信件在早晨邮件中送达。","targetForm":"mail","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Reliable mail services remain important for rural communities with limited internet access.","translation":"对网络接入有限的农村社区而言，可靠邮政服务仍然重要。","targetForm":"mail","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Please mail the signed form before Friday so that the application can be processed on time.","translation":"请在周五前邮寄签署表格，以便申请能及时处理。","targetForm":"mail","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The museum displayed a shirt of mail to show how soldiers once protected themselves.","translation":"博物馆展示了一件锁子甲，以说明士兵过去如何保护自己。","targetForm":"mail","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"She sent an email rather than ordinary mail because the deadline was close.","translation":"由于截止日期临近，她发送电子邮件而非普通邮寄。","targetForm":"mail","senseId":"source-other-1","sourceSenseId":"other-1"}]},"market":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"集市"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"市场"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"销售"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"使上市"}],"examples":[{"sentence":"The farmers' market allows small producers to sell fresh food directly to local residents.","translation":"农贸市场让小生产者能直接向当地居民出售新鲜食品。","targetForm":"market","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The company entered the market only after testing whether customers wanted the new service.","translation":"该公司只有在测试客户是否需要新服务后才进入市场。","targetForm":"market","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Housing prices rose when the market expected interest rates to fall.","translation":"当市场预期利率下降时，房价上涨了。","targetForm":"market","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The firm markets its product as a practical way to reduce household energy use.","translation":"该公司将产品推销为降低家庭能耗的实用途径。","targetForm":"markets","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"A company should not market a health product before its safety has been properly tested.","translation":"在健康产品安全性得到恰当测试前，公司不应将其推向市场。","targetForm":"market","senseId":"source-v-2","sourceSenseId":"v-2"}]},"maybe":{"senseGroups":[{"id":"source-adv-1","partOfSpeech":"adv.","sourceSenseIds":["adv-1"],"sense":"也许"}],"examples":[{"sentence":"Maybe the Electoral College isn’t such a peculiar idea, after all.","translation":"毕竟，选举人团理念或许并没有那么特殊。","targetForm":"maybe","senseId":"source-adv-1","sourceSenseId":"adv-1"}]},"male":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"男性的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"雄性的"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"雄性动物"}],"examples":[{"sentence":"The survey included an equal number of male and female participants.","translation":"调查纳入了数量相等的男性和女性参与者。","targetForm":"male","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The male bird built a nest before the breeding season began.","translation":"繁殖季开始前，雄鸟筑好了巢。","targetForm":"male","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The researchers separated the males from the females to observe their different behaviour.","translation":"研究人员将雄性与雌性分开，以观察它们不同的行为。","targetForm":"males","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"A healthy male population is essential for the species to reproduce successfully.","translation":"健康的雄性种群对该物种成功繁殖至关重要。","targetForm":"male","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The report examined whether male applicants received the same opportunities as female applicants.","translation":"报告审查男性申请人是否获得与女性申请人相同的机会。","targetForm":"male","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"management":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"管理"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"管理处","contextReviewed":true}],"examples":[{"sentence":"Good time management allows students to balance coursework, rest, and part-time employment.","translation":"良好的时间管理使学生能平衡课业、休息和兼职工作。","targetForm":"management","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The management of the hospital introduced a clearer system for reporting safety concerns.","translation":"医院管理层推出了更清晰的安全问题报告制度。","targetForm":"management","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"Effective water management is essential in regions that face longer and drier summers.","translation":"在夏季更长、更干燥的地区，有效水资源管理至关重要。","targetForm":"management","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The building's management responded quickly after residents reported a fault in the lift.","translation":"居民报告电梯故障后，楼宇管理处迅速作出回应。","targetForm":"management","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The course combines financial management with practical training in communication and leadership.","translation":"该课程将财务管理与沟通和领导力的实践训练相结合。","targetForm":"management","senseId":"source-n-3","sourceSenseId":"n-3"}]},"mate":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"助手"}],"examples":[{"sentence":"After my work mate quit his job he moved to Shanghai to teach English.","translation":"我的同事辞职了，后来去上海教英语。","targetForm":"mate","senseId":"source-n-3","sourceSenseId":"n-3"}]},"mad":{"senseGroups":[{"id":"source-adj-4","partOfSpeech":"adj.","sourceSenseIds":["adj-4"],"sense":"愚蠢的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"生气的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"疯狂的"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"狂怒"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"发疯的"}],"examples":[{"sentence":"It would be mad to ignore the safety warning simply because the journey is familiar.","translation":"仅因旅程熟悉就忽视安全警告是愚蠢的。","targetForm":"mad","senseId":"source-adj-4","sourceSenseId":"adj-4"},{"sentence":"She was mad at the company for charging a fee that had never been mentioned.","translation":"公司收取一项从未说明的费用，她对此很生气。","targetForm":"mad","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The crowd gave a mad cheer when the final result appeared on the screen.","translation":"最终结果出现在屏幕上时，人群发出狂热的欢呼。","targetForm":"mad","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The museum explains how the label mad was once used to exclude people with mental illness.","translation":"博物馆说明旧标签mad曾如何被用来排斥精神疾病患者。","targetForm":"mad","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"He was nearly mad with worry while he waited for news from the hospital.","translation":"他等待医院消息时，几乎因担忧而发狂。","targetForm":"mad","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"masterpiece":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"杰作"}],"examples":[{"sentence":"He was surprised to find the great artist's masterpiece hung on the wall upside down.","translation":"他实在有点不能相信，堂堂一个大画家的杰作，居然会被上下倒转地挂在墙上。","targetForm":"masterpiece","senseId":"source-n-1","sourceSenseId":"n-1"}]},"majority":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"多数"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"大半"}],"examples":[{"sentence":"The majority of residents supported the plan after the council explained its long-term benefits.","translation":"市议会说明长期益处后，大多数居民支持该计划。","targetForm":"majority","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A clear majority voted to protect the wetland from further development.","translation":"明显多数投票支持保护湿地免受进一步开发。","targetForm":"majority","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The majority of the research was completed before the funding ended unexpectedly.","translation":"资助意外结束前，大部分研究已经完成。","targetForm":"majority","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"In a democracy, the majority must still respect the rights of smaller groups.","translation":"在民主制度中，多数人仍必须尊重较小群体的权利。","targetForm":"majority","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The proposal passed by a narrow majority after several members changed their minds.","translation":"数名成员改变想法后，该提案以微弱多数获得通过。","targetForm":"majority","senseId":"source-n-1","sourceSenseId":"n-1"}]},"main":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"干线"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"主要的"}],"examples":[{"sentence":"A burst water main disrupted traffic and left several streets without clean water.","translation":"一条供水干管爆裂，扰乱交通并使数条街道断水。","targetForm":"main","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The main purpose of the survey is to identify barriers to adult education.","translation":"该调查的主要目的是识别成人教育的障碍。","targetForm":"main","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The main body of the essay should develop evidence rather than repeat the introduction.","translation":"论文主体应展开证据，而非重复引言。","targetForm":"main","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The engine failed because a valve in the main fuel line had become blocked.","translation":"由于主燃油管线中的阀门堵塞，发动机发生故障。","targetForm":"main","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Her main concern was whether the proposal would benefit people on low incomes.","translation":"她最关心的是该提案是否会惠及低收入人群。","targetForm":"main","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"mark":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"痕迹"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"分数"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"做标记于"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"打分数"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"标志"}],"examples":[{"sentence":"The dark mark on the wall showed where water had entered during the storm.","translation":"墙上的深色痕迹表明暴风雨期间水曾从那里渗入。","targetForm":"mark","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"She received a high mark because her essay answered the question with relevant evidence.","translation":"她的论文用相关证据回答问题，因此获得高分。","targetForm":"mark","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Please mark the locations where the pavement becomes unsafe after heavy rain.","translation":"请标记暴雨后人行道变得不安全的位置。","targetForm":"mark","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The teacher marked the reports promptly and explained the most common errors.","translation":"老师迅速批改报告，并解释了最常见的错误。","targetForm":"marked","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The new agreement marks an important step toward improving regional cooperation.","translation":"新协议标志着改善区域合作的重要一步。","targetForm":"marks","senseId":"source-v-5","sourceSenseId":"v-5"}]},"magnificent":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"华丽的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"高尚的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"宏伟的"}],"examples":[{"sentence":"The restored theatre has a magnificent ceiling painted with scenes from local history.","translation":"修复后的剧院有一幅华丽天花板，上面绘有当地历史场景。","targetForm":"magnificent","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The volunteers made a magnificent effort to deliver food during the severe snowstorm.","translation":"志愿者在严重暴风雪期间为运送食物付出了非凡努力。","targetForm":"magnificent","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"From the hill, we had a magnificent view of the river winding through the valley.","translation":"从山上望去，我们看到了河流蜿蜒穿过山谷的壮丽景色。","targetForm":"magnificent","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The museum's magnificent collection attracts researchers as well as ordinary visitors.","translation":"博物馆宏伟的藏品吸引研究人员和普通游客。","targetForm":"magnificent","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"It was magnificent of her to donate the prize money to a community education fund.","translation":"她将奖金捐给社区教育基金，十分高尚。","targetForm":"magnificent","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"make":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"制造"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"安排"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"使得"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"构造"},{"id":"source-v-15","partOfSpeech":"v.","sourceSenseIds":["v-15"],"sense":"增大"}],"examples":[{"sentence":"The company makes affordable solar lamps for households without reliable electricity.","translation":"该公司为缺乏可靠供电的家庭制造价格可负担的太阳能灯。","targetForm":"makes","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Please make a realistic timetable before you begin preparing for the examination.","translation":"开始备考前，请制定一个现实的时间表。","targetForm":"make","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"A clear explanation can make a difficult scientific idea easier for the public to understand.","translation":"清晰解释能让公众更容易理解艰深的科学概念。","targetForm":"make","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"The make of the bicycle was easy to identify from the distinctive frame design.","translation":"从独特车架设计很容易辨认出这辆自行车的品牌和型号。","targetForm":"make","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Careful preparation helped the team make up time after the early delay.","translation":"周密准备帮助团队在早期延误后赶回进度。","targetForm":"make","senseId":"source-v-15","sourceSenseId":"v-15"}]},"mass":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"块"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"质量"}],"examples":[{"sentence":"In the valley, the thin mist rose slowly like white feathers, turning into a mass of white clouds that shrouded everything.","translation":"山谷中，薄雾如白色羽毛般缓缓升腾，化作一团白云，遮蔽了一切。","targetForm":"mass","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The application allows you to quickly calculate the ratio of body mass index - BMI.","translation":"这项应用程序能让你快速计算身高体重指数（BMI）。","targetForm":"mass","senseId":"source-n-3","sourceSenseId":"n-3"}]},"machinery":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"机器"}],"examples":[{"sentence":"Then arose the question of where we were to get the necessary machinery.","translation":"于是出现了一个问题，哪里能找我们需要的机器。","targetForm":"machinery","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"An old worker was found repairing machinery in the workshop.","translation":"有人发现一个老工人在车间修机器。","targetForm":"machinery","senseId":"source-n-1","sourceSenseId":"n-1"}]},"magnify":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"扩大"}],"examples":[{"sentence":"All of these events have disturbed and disoriented Turkey, and are magnified by the domestic impact of worst global economic crisis since the 1930’s.","translation":"所有这些事件都让土耳其感到不安和无所适从，这些事件并因20世纪30年代以来最严重的全球性经济危机对国内的影响而被放大。","targetForm":"magnified","senseId":"source-v-2","sourceSenseId":"v-2"}]},"manner":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"礼貌"},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"方法","contextReviewed":true},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"风格"}],"examples":[{"sentence":"It is bad manners to make a noise while you eat.","translation":"吃饭时发出声音是不礼貌的。","targetForm":"manners","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"There is nothing worse than doing something in a half-hearted manner.","translation":"没有什么比做事缺乏热情更糟。","targetForm":"manner","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"George did business in the same manner as his father.","translation":"乔治和他爸爸做生意的方式一样。","targetForm":"manner","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"The manners and customs of a country reflect its culture.","translation":"一个国家的风俗习惯反映了它的文化。","targetForm":"manners","senseId":"source-n-3","sourceSenseId":"n-3"}]},"mainland":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"本土"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"大陆"}],"examples":[{"sentence":"Tomorrow, I am coming back from Hong Kong to the mainland.","translation":"明天我要从香港去趟内地。","targetForm":"mainland","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The mainland of China covers 96,000,000 square kilometers, and it is the largest country in Asia, as well as the third largest in the world.","translation":"中国陆地的总面积是960万平方公里，是亚洲面积最大的国家，居世界第三位。","targetForm":"mainland","senseId":"source-n-1","sourceSenseId":"n-1"}]},"manager":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"经理"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"管理员"},{"id":"source-other-1","partOfSpeech":"计算机","sourceSenseIds":["other-1"],"sense":"管理器","contextReviewed":true}],"examples":[{"sentence":"The manager met the staff to explain why the store would change its opening hours.","translation":"经理会见员工，解释商店为何要改变营业时间。","targetForm":"manager","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A museum manager must protect valuable objects while making them accessible to the public.","translation":"博物馆经理必须保护珍贵物品，同时让公众能够接触它们。","targetForm":"manager","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The building manager arranged repairs after several residents reported a leaking pipe.","translation":"多位居民报告水管漏水后，楼宇管理员安排了维修。","targetForm":"manager","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The password manager creates unique passwords without requiring users to remember every detail.","translation":"密码管理器创建唯一密码，无需用户记住每个细节。","targetForm":"manager","senseId":"source-other-1","sourceSenseId":"other-1"},{"sentence":"Her manager encouraged her to take responsibility for a small but important project.","translation":"她的经理鼓励她负责一个虽小但重要的项目。","targetForm":"manager","senseId":"source-n-1","sourceSenseId":"n-1"}]},"manipulate":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"操纵"}],"examples":[{"sentence":"And, third, laws intended to protect private information should be reevaluated to ensure that IT companies are unable to profit from exploiting and manipulating it.","translation":"最重要的是，公众必须更加深刻地理解IT的经济效应，特别是改善了如此多的人的生活的技术如何只让如此少的人致富。","targetForm":"manipulating","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"You will know you have succeeded when the United States’ Treasury Secretary comes knocking on your door saying that you are guilty of manipulating your currency.","translation":"当美国的财政部长敲开你家大门，告诉你你因操纵货币而有罪时，你就会明白你已经大功告成。","targetForm":"manipulating","senseId":"source-v-1","sourceSenseId":"v-1"}]},"master":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"大师"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"主人"}],"examples":[{"sentence":"If you concentrate all your energies on the study of English, you will master the language.","translation":"你如果能把全副精力放进去，要学会英文并不是难事。","targetForm":"master","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"There's a train station in Japan where the station master is a cat.","translation":"在日本，有站长是猫的车站。","targetForm":"master","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When one is in difficulty and comports themselves well, that is a master.","translation":"人之患，在好为人师。","targetForm":"master","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"My home is on the eighteenth floor, and both the master bedroom and the living room face south.","translation":"我家在十八层，主卧和客厅都面朝南方。","targetForm":"master","senseId":"source-n-1","sourceSenseId":"n-1"}]},"match":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"比赛"}],"examples":[{"sentence":"I do really want to watch this match, but I'm not sure if I have the time.","translation":"我倒是很想去看这场比赛，可是不知道有没有时间。","targetForm":"match","senseId":"source-n-1","sourceSenseId":"n-1"}]}}};
